"""Validate the static site generated by build_site.py in stage-47/site."""

from __future__ import annotations

import json
import re
import subprocess
import sys
import tempfile
import urllib.parse
from pathlib import Path

ROOT = Path(__file__).resolve().parent
SITE = ROOT / "site"

sys.path.insert(0, str(ROOT))
from build_site import CHAPTERS, LANG_INFO, LANGS, SITE_URL, STRINGS, lang_dir  # noqa: E402

errors: list[str] = []
warnings: list[str] = []
_checked_script_bodies: set[str] = set()


def fail(message: str) -> None:
    errors.append(message)


def node_available() -> bool:
    try:
        subprocess.run(["node", "--version"], capture_output=True, check=True)
        return True
    except (FileNotFoundError, subprocess.CalledProcessError):
        return False


NODE_AVAILABLE = node_available()
if not NODE_AVAILABLE:
    warnings.append("node not found on PATH; skipping inline <script> syntax checks")

CARD_ID_RE = re.compile(r'<article class="stage" id="(stage-(\d+)-(\d+))"')
SCRIPT_RE = re.compile(r"<script([^>]*)>(.*?)</script>", re.DOTALL)
CANONICAL_RE = re.compile(r'<link rel="canonical" href="([^"]+)">')
H1_RE = re.compile(r"<h1\b([^>]*)>(.*?)</h1>", re.DOTALL)
TITLE_RE = re.compile(r"<title>(.*?)</title>", re.DOTALL)
DESCRIPTION_RE = re.compile(r'<meta name="description" content="([^"]*)">')
HREFLANG_RE = re.compile(r'<link rel="alternate" hreflang="([A-Za-z-]+)" href="([^"]+)">')
JSONLD_RE = re.compile(r'<script type="application/ld\+json">(.*?)</script>', re.DOTALL)
OG_IMAGE_RE = re.compile(r'<meta property="og:image" content="([^"]+)">')


def check_inline_scripts(rel: Path, text: str) -> None:
    if not NODE_AVAILABLE:
        return
    for attrs, body in SCRIPT_RE.findall(text):
        if 'type="application/ld+json"' in attrs or "src=" in attrs or not body.strip():
            continue
        if body in _checked_script_bodies:
            continue
        _checked_script_bodies.add(body)
        with tempfile.NamedTemporaryFile("w", suffix=".js", delete=False) as handle:
            handle.write(body)
            temp_path = handle.name
        try:
            result = subprocess.run(["node", "--check", temp_path], capture_output=True, text=True)
            if result.returncode != 0:
                fail(f"{rel}: inline script failed node --check: {result.stderr.strip()}")
        finally:
            Path(temp_path).unlink(missing_ok=True)


def check_page(path: Path) -> None:
    text = path.read_text()
    rel = path.relative_to(SITE)

    if "chapter-pagination" in text:
        fail(f"{rel}: removed chapter pagination still present")

    for removed in ('chapter-share-btn', 'chapter-copy-btn', 'card-share',
                    'toastCopied', 'navigator.share', "gaEvent('share'"):
        if removed in text:
            fail(f"{rel}: removed share feature still present: {removed}")

    for removed in ('stage-search-form', 'stage-search-input', 'stage-search-status',
                    'search-btn', 'stage_search', 'e.g. 31-45', 'ví dụ: 31-45',
                    '?stage=', 'SearchAction', 'pendingStageSearch', 'parseStageQuery'):
        if removed in text:
            fail(f"{rel}: removed search feature still present: {removed}")

    if '<meta name="viewport" content="width=device-width, initial-scale=1">' not in text:
        fail(f"{rel}: missing mobile viewport meta tag")
    for attrs in re.findall(r'<img\b([^>]+)>', text):
        if not ('width="' in attrs and 'height="' in attrs):
            fail(f"{rel}: image missing explicit dimensions")

    canonicals = CANONICAL_RE.findall(text)
    if len(canonicals) != 1:
        fail(f"{rel}: expected exactly one canonical link, found {len(canonicals)}")

    h1s = H1_RE.findall(text)
    if len(h1s) != 1:
        fail(f"{rel}: expected exactly one <h1>, found {len(h1s)}")

    page_lang = next((l for l in LANGS if LANG_INFO[l]["prefix"] and rel.parts[0] == LANG_INFO[l]["prefix"].lstrip("/")),
                     "en")
    prefix = LANG_INFO[page_lang]["prefix"]
    is_chapter = "chapter" in rel.parts
    is_home = rel == lang_dir(Path("."), page_lang) / "index.html"
    if f'<html lang="{LANG_INFO[page_lang]["code"]}">' not in text:
        fail(f"{rel}: expected <html lang=\"{LANG_INFO[page_lang]['code']}\">")
    switch = re.search(r'<select id="lang-select">(.*?)</select>', text, re.DOTALL)
    options = re.findall(r'<option value="([^"]+)" data-lang="([^"]+)"[^>]*?( selected)?>', switch.group(1)) if switch else []
    if [lang for _, lang, _ in options] != list(LANGS):
        fail(f"{rel}: language dropdown should list {list(LANGS)}, found {[lang for _, lang, _ in options]}")
    if [lang for _, lang, sel in options if sel] != [page_lang]:
        fail(f"{rel}: language dropdown should select {page_lang}")
    for href, lang, _ in options:
        target = SITE / href.lstrip("/") / "index.html" if href.endswith("/") else SITE / href.lstrip("/")
        if not target.exists():
            fail(f"{rel}: language dropdown links to missing page {href}")
    if "lang-switch" in text:
        fail(f"{rel}: old language link row still present")
    has_feedback = 'id="feedback-form"' in text
    if (is_chapter or is_home) != has_feedback:
        fail(f"{rel}: feedback form should appear on home and chapter pages only")
    if has_feedback and 'name="website"' not in text:
        fail(f"{rel}: feedback form missing honeypot field")
    if is_chapter:
        chapter_n = int(rel.parts[rel.parts.index("chapter") + 1])
        next_links = re.findall(r'<a class="next-stage-link" href="([^"]+)"', text)
        expected = [f"{prefix}/chapter/{chapter_n + 1}/"] if (SITE / "chapter" / str(chapter_n + 1)).exists() else []
        if next_links != expected:
            fail(f"{rel}: expected next-stage link {expected}, found {next_links}")
    if 'class="intro"' in text:
        fail(f"{rel}: removed intro section still present")
    if is_home and "fan-made reference" in text:
        fail(f"{rel}: removed home intro text still present")
    if len(h1s) == 1:
        classes = re.search(r'class=[\"\']([^\"\']*)[\"\']', h1s[0][0])
        hidden = classes is not None and "sr-only" in classes.group(1).split()
        if (is_chapter or is_home) and not hidden:
            fail(f"{rel}: home/chapter h1 must have class sr-only")
        elif not (is_chapter or is_home) and hidden:
            fail(f"{rel}: privacy h1 must remain visible")

    titles = TITLE_RE.findall(text)
    if len(titles) != 1 or not titles[0].strip():
        fail(f"{rel}: expected exactly one non-empty <title>, found {len(titles)}")

    descriptions = DESCRIPTION_RE.findall(text)
    if len(descriptions) != 1 or not descriptions[0].strip():
        fail(f"{rel}: expected exactly one non-empty meta description, found {len(descriptions)}")

    hreflangs = {lang for lang, _ in HREFLANG_RE.findall(text)}
    expected_hreflangs = {LANG_INFO[l]["code"] for l in LANGS} | {"x-default"}
    if hreflangs != expected_hreflangs:
        fail(f"{rel}: expected hreflang {sorted(expected_hreflangs)}, found {sorted(hreflangs)}")

    for match in JSONLD_RE.findall(text):
        try:
            json.loads(match)
        except json.JSONDecodeError as error:
            fail(f"{rel}: invalid JSON-LD ({error})")

    og_images = OG_IMAGE_RE.findall(text)
    if not og_images:
        fail(f"{rel}: missing og:image meta tag")
    for image_url in og_images:
        image_path = SITE / urllib.parse.urlparse(image_url).path.lstrip("/")
        if not image_path.exists():
            fail(f"{rel}: og:image file missing: {image_path.relative_to(SITE)}")

    check_inline_scripts(rel, text)


def sitemap_loc_to_path(loc: str) -> Path:
    parsed_path = urllib.parse.urlparse(loc).path
    if parsed_path.endswith("/"):
        return SITE / parsed_path.lstrip("/") / "index.html"
    return SITE / parsed_path.lstrip("/")


def main() -> None:
    if not SITE.exists():
        fail("site directory does not exist; run build_site.py first")
        report()
        return

    if (SITE / "chapters").exists():
        fail("stale stage-47/site/chapters/ directory found; it should no longer be generated")

    english_keys = set(STRINGS["en"])
    for lang in LANGS:
        if set(STRINGS[lang]) != english_keys:
            fail(f"STRINGS[{lang!r}] keys differ from English: "
                 f"missing {sorted(english_keys - set(STRINGS[lang]))}, extra {sorted(set(STRINGS[lang]) - english_keys)}")
        if len(STRINGS[lang]["privacy_sections"]) != len(STRINGS["en"]["privacy_sections"]):
            fail(f"STRINGS[{lang!r}]: privacy_sections count differs from English")

    pages_to_check: list[Path] = []
    for page in [lang_dir(SITE, lang) / name for lang in LANGS for name in ("index.html", "privacy.html")]:
        if page.exists():
            pages_to_check.append(page)
        else:
            fail(f"missing expected page: {page.relative_to(SITE)}")

    chapter_numbers = sorted(c["chapter"] for c in CHAPTERS)
    total_cards = {lang: 0 for lang in LANGS}
    for lang in LANGS:
        chapter_dir = lang_dir(SITE, lang) / "chapter"
        found = (sorted(int(p.name) for p in chapter_dir.iterdir() if p.is_dir())
                 if chapter_dir.exists() else [])
        if found != chapter_numbers:
            fail(f"{lang}: expected {len(chapter_numbers)} chapter pages, found {len(found)}")
        for number in chapter_numbers:
            page = chapter_dir / str(number) / "index.html"
            if not page.exists():
                fail(f"missing chapter page: {page.relative_to(SITE)}")
                continue
            pages_to_check.append(page)
            text = page.read_text()
            card_ids = CARD_ID_RE.findall(text)
            ids_only = [card_id for card_id, _, _ in card_ids]
            if len(ids_only) != len(set(ids_only)):
                fail(f"{page.relative_to(SITE)}: duplicate stage anchor ids")
            for card_id, chapter_str, _ in card_ids:
                if int(chapter_str) != number:
                    fail(f"{page.relative_to(SITE)}: card id {card_id} chapter mismatch")
            total_cards[lang] += len(card_ids)
            if text.count('class="report-btn"') != len(card_ids):
                fail(f"{page.relative_to(SITE)}: every card needs one \"can't pass\" report button")
            for card_id, card_chapter, first_stage, stages_attr in re.findall(
                    r'<article class="stage" id="(stage-(\d+)-(\d+))"[^>]*?data-stages="([\d,]+)"', text):
                if stages_attr.split(",")[0] != first_stage:
                    fail(f"{page.relative_to(SITE)}: {card_id} data-stages should start at its first stage")

    for lang in LANGS:
        if total_cards[lang] != 2129:
            fail(f"{lang} chapter pages: expected 2129 total cards, found {total_cards[lang]}")

    for page in pages_to_check:
        check_page(page)

    robots_path = SITE / "robots.txt"
    if not robots_path.exists():
        fail("robots.txt missing")
    else:
        robots_text = robots_path.read_text()
        if f"Sitemap: {SITE_URL}/sitemap.xml" not in robots_text:
            fail("robots.txt missing Sitemap line")

    sitemap_path = SITE / "sitemap.xml"
    if not sitemap_path.exists():
        fail("sitemap.xml missing")
    else:
        sitemap_text = sitemap_path.read_text()
        locs = re.findall(r"<loc>([^<]+)</loc>", sitemap_text)
        if not locs:
            fail("sitemap.xml has no <loc> entries")
        for loc in locs:
            file_path = sitemap_loc_to_path(loc)
            if not file_path.exists():
                fail(f"sitemap.xml: URL does not map to an existing file: {loc}")

    report()


def report() -> None:
    for warning in warnings:
        print(f"WARNING: {warning}")
    if errors:
        for error in errors:
            print(f"ERROR: {error}")
        print(f"\ncheck_site.py failed with {len(errors)} error(s).")
        sys.exit(1)
    print(f"check_site.py passed ({len(warnings)} warning(s)).")


if __name__ == "__main__":
    main()
